// The CLI "other device" fixture of the M1-S5 contract suite (docs/test-plans/M1-S5.md §Fixtures; ADR-0007
// `e2eeAccount`). It stands in for the user's desktop or phone: a fresh profile that joins the test's sync account,
// turns E2EE on, creates a folder and notes, and syncs. As found in spike S3, `e2ee enable` persists the master key
// only when it runs inside `joplin batch` together with `sync` (CLI 3.7.1), so everything runs in one batch.
// Input (stdin, one JSON object; never argv, so the passwords stay out of /proc/*/cmdline):
//   {"syncUrl","email","password","masterPassword","folder","notes":[{"title","body"}],
//    "extras"?: {"todo":{"title","due"},"tag":{"title","note"},"attachment":{"note","fileName","contentBase64"}}}
// The seed sync must succeed (DNS-1, DNS1-AC4): after the batch the output needs a `Completed:` line and no line with
// `Last error:`. Otherwise the device writes `SEED SYNC FAILED: <that line>` to stderr and exits 3, before `RESULT`.
// It never retries: a retry would hide the very class of fault (a proxy 502) the check exists to surface. The CLI exits 0
// after a failed sync, so without this check the master key is never uploaded and the failure shows up much later.
// Output: the CLI's output, then one last line
//   `RESULT {"e2ee": "...", "notes": [{"id","title"}], "todo"?: {"id","title"}, "attachmentNote"?: {"id","title"}}`.
// `extras` is optional (docs/test-plans/M2-S2.md D7): a to-do with todo_due (epoch ms), a tag on a note, and a note with
// a text attachment, all created before the sync.
// Titles, bodies and the folder name are generated by the test: no quotes, backslashes or newlines.
import { spawn } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const readStdin = async () => {
	const chunks = [];
	for await (const chunk of process.stdin) chunks.push(chunk);
	return JSON.parse(Buffer.concat(chunks).toString('utf8'));
};

const joplin = (profile, args, input) => new Promise((resolve, reject) => {
	const child = spawn('joplin', ['--profile', profile, ...args], { stdio: ['pipe', 'pipe', 'pipe'] });
	let output = '';
	child.stdout.on('data', chunk => {
		output += chunk;
		process.stdout.write(chunk);
	});
	child.stderr.on('data', chunk => {
		output += chunk;
		process.stderr.write(chunk);
	});
	child.on('error', reject);
	child.on('close', code => (code === 0 ? resolve(output) : reject(new Error(`joplin ${args[0]} exited ${code}`))));
	child.stdin.end(input ?? '');
});

const plan = await readStdin();
const extras = plan.extras;
const batchValues = [plan.folder, ...plan.notes.flatMap(n => [n.title, n.body])];
if (extras) batchValues.push(extras.todo.title, extras.tag.title, extras.tag.note, extras.attachment.note);
for (const value of batchValues) {
	if (/["\\\n\r]/.test(value)) throw new Error(`unsafe batch value: ${JSON.stringify(value)}`);
}
if (extras) {
	if (!Number.isSafeInteger(extras.todo.due)) throw new Error(`unsafe todo_due: ${JSON.stringify(extras.todo.due)}`);
	if (!/^[a-z0-9.-]+$/.test(extras.attachment.fileName)) throw new Error(`unsafe attachment file name: ${JSON.stringify(extras.attachment.fileName)}`);
}
const profile = '/tmp/home/device-profile';
mkdirSync(profile, { recursive: true, mode: 0o700 });
const attachmentPath = extras ? join('/tmp/home', extras.attachment.fileName) : '';
if (extras) writeFileSync(attachmentPath, Buffer.from(extras.attachment.contentBase64, 'base64'), { mode: 0o600 });

await joplin(profile, ['config', '--import'], JSON.stringify({
	'sync.target': 9,
	'sync.9.path': plan.syncUrl,
	'sync.9.username': plan.email,
	'sync.9.password': plan.password,
}));

const batch = [
	`e2ee enable --password "${plan.masterPassword}"`,
	`mkbook "${plan.folder}"`,
	`use "${plan.folder}"`,
	...plan.notes.flatMap(n => [`mknote "${n.title}"`, `set "${n.title}" body "${n.body}"`]),
	...(extras ? [
		`mktodo "${extras.todo.title}"`,
		`set "${extras.todo.title}" todo_due ${extras.todo.due}`,
		`tag add "${extras.tag.title}" "${extras.tag.note}"`,
		`mknote "${extras.attachment.note}"`,
		`attach "${extras.attachment.note}" "${attachmentPath}"`,
	] : []),
	'sync',
	'ls --format json',
].join('\n');
const batchFile = '/tmp/home/device-batch.txt';
writeFileSync(batchFile, `${batch}\n`, { mode: 0o600 });
const output = await joplin(profile, ['batch', batchFile]);

const outputLines = output.split('\n');
const lastError = outputLines.find(line => line.includes('Last error:'));
if (lastError !== undefined || !outputLines.some(line => line.includes('Completed:'))) {
	process.stderr.write(`\nSEED SYNC FAILED: ${lastError ?? 'the batch printed no `Completed:` line'}\n`);
	process.exit(3);
}

const listed = output.split('\n').filter(line => line.startsWith('[')).pop();
if (!listed) throw new Error('the batch printed no `ls --format json` line');
const items = JSON.parse(listed);
const notes = plan.notes.map(n => {
	const item = items.find(i => i.title === n.title);
	if (!item) throw new Error(`note ${JSON.stringify(n.title)} not listed after the batch`);
	return { id: item.id, title: n.title };
});

const found = title => {
	const item = items.find(i => i.title === title);
	if (!item) throw new Error(`${JSON.stringify(title)} not listed after the batch`);
	return { id: item.id, title };
};

const status = await joplin(profile, ['e2ee', 'status']);
const e2ee = /Encryption is:\s*(\w+)/.exec(status)?.[1] ?? 'unknown';
const result = { e2ee, notes };
if (extras) {
	result.todo = found(extras.todo.title);
	result.attachmentNote = found(extras.attachment.note);
}
process.stdout.write(`\nRESULT ${JSON.stringify(result)}\n`);
